SELECT 
FROM department d
LEFT JOIN department p ON p.department_id = d.parent_department_id


        AND (
            LOWER(d.department_code) LIKE CONCAT('%', LOWER(#{keyword}), '%')
            OR LOWER(d.department_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
        )


        AND d.active = #{active}


ORDER BY d.department_code ASC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM department d
AND ( LOWER(d.department_code) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(d.department_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') )
AND d.active = #{active}
